import { spawnSync } from "node:child_process";
import module from "node:module";

/**
 * Built-in syntax parsers that need nothing beyond the evaluation host's own Node.js and Python:
 * - TypeScript (.ts, .mts, .cts): Node's built-in TypeScript parser (`module.stripTypeScriptTypes`, transform mode),
 *   which parses the whole file and throws on any syntax error. Requires Node.js >= 22.13; older hosts have no default.
 * - JavaScript (.js, .mjs, .cjs): `node --check` on the file itself, so the module type follows the file's extension
 *   and nearest package.json exactly as Node would run it.
 * - Python (.py): `ast.parse` in an isolated interpreter (`python3 -I`), source on stdin.
 * Rust, TSX and JSX have no built-in parser; callers that need them supply one, and otherwise those files fail closed.
 * Each parser returns a small descriptor object on success and throws with the parser's message on failure.
 */

const CHILD_ENV = () => ({ PATH: process.env.PATH ?? "", LANG: "C.UTF-8", LC_ALL: "C.UTF-8" });
const TIMEOUT_MS = 30_000;

function childFailure(result, what) {
  if (result.error) return `${what} could not run: ${result.error.message}`;
  if (result.signal) return `${what} was terminated by ${result.signal}`;
  const text = `${result.stderr ?? ""}${result.stdout ?? ""}`.trim().split(/\r?\n/).filter(Boolean);
  return text.slice(-3).join(" | ") || `${what} exited with status ${result.status}`;
}

function parseTypeScript(source) {
  const strip = module.stripTypeScriptTypes;
  if (typeof strip !== "function") throw new Error("no built-in TypeScript parser on this Node.js (requires >= 22.13)");
  strip(source, { mode: "transform" });
  return { parser: "node:module.stripTypeScriptTypes" };
}

function parseJavaScript(_source, { absolutePath }) {
  const result = spawnSync(process.execPath, ["--check", absolutePath], { env: CHILD_ENV(), timeout: TIMEOUT_MS, encoding: "utf8", shell: false });
  if (result.status !== 0 || result.signal || result.error) throw new Error(childFailure(result, "node --check"));
  return { parser: "node --check" };
}

function parsePython(source, { file }) {
  const program = "import ast, sys\nast.parse(sys.stdin.buffer.read(), filename=sys.argv[1])";
  const result = spawnSync("python3", ["-I", "-c", program, file], { input: source, env: CHILD_ENV(), timeout: TIMEOUT_MS, encoding: "utf8", shell: false });
  if (result.status !== 0 || result.signal || result.error) throw new Error(childFailure(result, "python3 ast.parse"));
  return { parser: "python3 ast.parse" };
}

export const DEFAULT_PARSERS = Object.freeze({ typescript: parseTypeScript, javascript: parseJavaScript, python: parsePython });
import { evaluatorResult } from "./result.mjs";

const KEYS = ["native", "trailing", "structural", "invalid"];

/**
 * Score tool-call argument syntax from the agent's own telemetry: the `toolCallSyntax` counts on each turn result
 * (`nexus run --json` → `turn.toolCallSyntax`). Native JSON scores 1, JSON recovered by a trailing or structural
 * repair 0.5, and arguments that did not parse 0. Any invalid call fails the pass bit; so does having no tool calls
 * recorded at all, since there is then nothing to score.
 */
export function evaluateJsonRepairRate(turns) {
  const list = Array.isArray(turns) ? turns : [turns];
  const counts = { native: 0, trailing: 0, structural: 0, invalid: 0 };
  for (const syntax of list) {
    if (syntax == null) continue; // a turn with no tool calls carries no counts
    if (typeof syntax !== "object") throw new TypeError("tool-call syntax counts must be objects");
    for (const key of KEYS) {
      const n = syntax[key] ?? 0;
      if (!Number.isSafeInteger(n) || n < 0) throw new TypeError(`tool-call syntax count ${key} must be a non-negative integer`);
      counts[key] += n;
    }
  }
  const total = KEYS.reduce((sum, key) => sum + counts[key], 0);
  const repaired = counts.trailing + counts.structural;
  const score = total ? (counts.native + 0.5 * repaired) / total : 0;
  return evaluatorResult("json_repair_rate", total > 0 && counts.invalid === 0, score, {
    total, ...counts, repaired, ...(total ? {} : { error: "no tool calls recorded" }),
  });
}
test("build passes only on a clean zero exit of the real command", async () => {
  const node = process.execPath;
  assert.equal((await ev.evaluateBuild({ command: node, args: ["-e", "process.exit(0)"] })).passed, true);
  const failed = await ev.evaluateBuild({ command: node, args: ["-e", "process.exit(3)"] });
  assert.equal(failed.passed, false);
  assert.equal(failed.details.status, 3);
  const slow = await ev.evaluateBuild({ command: node, args: ["-e", "setTimeout(() => {}, 10000)"], timeoutMs: 200 });
  assert.equal(slow.passed, false);
  assert.equal(slow.details.timedOut, true);
  const missing = await ev.evaluateBuild({ command: "nexus-no-such-binary-wp1105" });
  assert.equal(missing.passed, false);
  assert.ok(missing.details.error, "spawn failure is reported");
  // The command never runs through a shell.
  const run = await runArgv(node, ["-e", "console.log(process.argv[1])", "$(echo injected)"]);
  assert.equal(run.stdout.trim(), "$(echo injected)");
  // The command sees a minimal environment, not the evaluator's.
  process.env.NEXUS_WP1105_SECRET = "REDACTED";
  try {
    const env = await runArgv(node, ["-e", "console.log(JSON.stringify(Object.keys(process.env).sort()))"]);
    assert.deepEqual(JSON.parse(env.stdout), ["HOME", "LANG", "PATH", "PWD"]);
  } finally {
    delete process.env.NEXUS_WP1105_SECRET;
  }
});

test("typecheck_clean fails only on diagnostics the candidate adds, and on infrastructure failure", async () => {
  const same = (stderr: string) => async () => ({ status: 1, stderr });
  const spec = (command: string, cwd: string) => ({ command, args: ["--noEmit"], cwd });
  const unchanged = await ev.evaluateTypecheckClean({ baseline: spec("b", "/tmp/base"), candidate: spec("c", "/tmp/cand"), runner: same("a.ts(1,1): error TS1: existing") });
  assert.equal(unchanged.passed, true);
  const added = await ev.evaluateTypecheckClean({
    baseline: spec("b", "/tmp/base"), candidate: spec("c", "/tmp/cand"),
    runner: async (command: string) => ({ status: 1, stderr: command === "b" ? "same\n" : "same\nsame\nnew" }),
  });
  assert.deepEqual(added.details.newDiagnostics, ["same", "new"]);
  assert.equal(added.passed, false);
  const crashed = await ev.evaluateTypecheckClean({ baseline: spec("b", "/tmp/base"), candidate: spec("c", "/tmp/cand"), runner: async (c: string) => (c === "b" ? { status: 0 } : { status: null, signal: "SIGKILL" }) });
  assert.equal(crashed.passed, false);
  assert.equal(crashed.details.infrastructureFailure, true);
  const silent = await ev.evaluateTypecheckClean({ baseline: spec("b", "/tmp/base"), candidate: spec("c", "/tmp/cand"), runner: async (c: string) => ({ status: c === "b" ? 0 : 2 }) });
  assert.equal(silent.passed, false, "a candidate that newly fails without output does not pass");
  assert.equal(silent.details.infrastructureFailure, true, "a nonzero checker run without a recognized diagnostic is not a valid comparison");
  // A failing baseline's exit code may differ from the candidate's without a regression when diagnostics do not grow.
  const fewer = await ev.evaluateTypecheckClean({
    baseline: spec("b", "/tmp/base"), candidate: spec("c", "/tmp/cand"),
    runner: async (c: string) => (c === "b" ? { status: 2, stderr: "error TS1001: e1\nerror TS1002: e2" } : { status: 1, stderr: "error TS1001: e1" }),
  });
  assert.equal(fewer.passed, true, JSON.stringify(fewer.details));
  const silentAfterFailure = await ev.evaluateTypecheckClean({ baseline: spec("b", "/tmp/base"), candidate: spec("c", "/tmp/cand"), runner: async (c: string) => (c === "b" ? { status: 2, stderr: "error TS1001: e1" } : { status: 2 }) });
  assert.equal(silentAfterFailure.passed, false, "a failing candidate with no diagnostics is not a pass");
  await assert.rejects(ev.evaluateTypecheckClean({ baseline: spec("b", "/tmp/x"), candidate: spec("c", "/tmp/x/") }), /must be separate/);
});

test("typecheck_clean rejects unavailable checkers on both revisions", async () => {
  const spec = (cwd: string) => ({ command: "tsc", args: ["--noEmit"], cwd });
  const unavailable = await ev.evaluateTypecheckClean({
    baseline: spec("/tmp/wp1105-baseline"),
    candidate: spec("/tmp/wp1105-candidate"),
    runner: async () => ({ status: 127, stdout: "", stderr: "Cannot find module 'typescript'" }),
  });
  assert.equal(unavailable.passed, false);
  assert.equal(unavailable.details.infrastructureFailure, true);
});

test("typecheck_clean rejects generic module errors as unavailable checker failures", async () => {
  const spec = (cwd: string) => ({ command: "tsc", args: ["--noEmit"], cwd });
  const unavailable = await ev.evaluateTypecheckClean({
    baseline: spec("/tmp/wp1105-baseline-without-typescript"),
    candidate: spec("/tmp/wp1105-candidate-without-typescript"),
    runner: async () => ({ status: 1, stderr: "Error: Cannot find module 'typescript'" }),
  });
  assert.equal(unavailable.passed, false, "the same missing-checker error on both sides cannot count as a clean comparison");
  assert.equal(unavailable.score, 0);
  assert.equal(unavailable.details.infrastructureFailure, true);
});

test("typecheck_clean rejects candidate syntax failures even when the checker is unavailable", async () => {
  const root = temporaryDirectory("typecheck-missing-typescript-");
  const baseline = path.join(root, "baseline");
  const candidate = path.join(root, "candidate");
  fs.mkdirSync(path.join(baseline, "src"), { recursive: true });
  fs.mkdirSync(path.join(candidate, "src"), { recursive: true });
  fs.writeFileSync(path.join(baseline, "src/index.ts"), "export const value = 1;\n");
  fs.writeFileSync(path.join(candidate, "src/index.ts"), "export const value: = ;\n");
  try {
    const spec = (cwd: string) => ({ command: "tsc", args: ["--noEmit"], cwd });
