const verdict = (runner: (cmd: string, args: string[], o: { cwd: string }) => any, extra: Record<string, unknown> = {}) =>
  ev.evaluateTypecheckClean({ baseline: spec("baseline"), candidate: spec("candidate"), runner, ...extra });
