export function runIsolatedProcess(spec, { outputLimit = 16_384, input = "", resources = null } = {}) {
  if (!Number.isFinite(spec.timeoutMs) || spec.timeoutMs <= 0) throw new Error("isolated process spec has no timeoutMs");
